import '@kerfjs/ui/layout.css';
import { Toolbar } from '@kerfjs/ui/toolbar';
import { ToolbarText } from '@kerfjs/ui/toolbar-text';
import { ToolbarControlGroup } from '@kerfjs/ui/toolbar-control-group';
import { SegmentedControl } from '@kerfjs/ui/segmented-control';
import { delegate } from './events';
import './view.css';

type View = 'board' | 'list' | 'timeline';
export function createWorkspaceView(root: HTMLElement, paint: (html: ReturnType<typeof Toolbar>) => void, onChange: (view: View) => void, initial: View = 'board') {
  let value = initial;
  const render = () => <div class="app-root kui-layout"><Toolbar label="Workspace controls"
    leading={<ToolbarText text="Workspace" />}
    trailing={<ToolbarControlGroup label="Workspace view" appearance="borderless"><SegmentedControl
      id="workspace-view" label="Workspace view" action="workspace-set-view"
      value={value} appearance="toolbar" size="small"
      choices={[{ value: 'board', label: 'Board' }, { value: 'list', label: 'List' }, { value: 'timeline', label: 'Timeline' }]}
    /></ToolbarControlGroup>} /></div>;
  const dispose = delegate(root, 'click', '[data-action="workspace-set-view"]', element => {
    const next = element.dataset.segmentValue;
    if (next !== 'board' && next !== 'list' && next !== 'timeline') return;
    if (next === value) return;
    value = next;
    paint(render());
    onChange(value); // App owns workspace rendering, routing, and persistence.
  });
  paint(render());
  // Enabled segment buttons retain native Tab, Enter, and Space behavior.
  return { render, dispose, setValue(next: View) { value = next; paint(render()); } };
}

